          "code": "import numpy as np\nfrom sklearn.ensemble import RandomForestRegressor\n\nrng = np.random.default_rng(42)\nn = 1200\nrho = 0.92\n\n# Pasangan fitur berkorelasi sangat tinggi (rho = 0.92):\n# X0 = luas_bangunan (terstandar), X1 = jumlah_kamar_terstandar\nz1 = rng.standard_normal(n)\nz2 = rng.standard_normal(n)\nx0 = z1\nx1 = rho * z1 + np.sqrt(1.0 - rho ** 2) * z2\nX = np.column_stack([x0, x1])\n\n# Ground-truth aditif: f(x0, x1) = 2.0 * x0 + 2.5 * x1 (efek sejati murni X0 = 2.0 * x0)\ny = 2.0 * x0 + 2.5 * x1 + rng.normal(0.0, 0.25, size=n)\n\n# Latih model pohon non-linier (Random Forest) pada manifold berkorelasi\nrf = RandomForestRegressor(n_estimators=45, max_depth=8, min_samples_leaf=5, random_state=42)\nrf.fit(X, y)\n\n# 1. Grid evaluasi berbasis kuantil X0 (K = 20 interval -> 60 sampel per interval)\nK = 20\nedges = np.quantile(x0, np.linspace(0.0, 1.0, K + 1))\nedges[0] -= 1e-6\nedges[-1] += 1e-6\nmids = 0.5 * (edges[:-1] + edges[1:])\n\n# 2. First-Principles PDP (integrasi terhadap marginal p(X1) -> ekstrapolasi off-manifold!)\npdp_raw = np.empty(K)\nfor k, val in enumerate(mids):\n    X_mod = X.copy()\n    X_mod[:, 0] = val\n    pdp_raw[k] = float(np.mean(rf.predict(X_mod)))\npdp_centered = pdp_raw - float(np.mean(pdp_raw))\n\n# 3. First-Principles M-Plot (rata-rata bersyarat dalam bin -> confounding oleh X1!)\nmplot_raw = np.empty(K)\nbin_ids = np.clip(np.digitize(x0, edges) - 1, 0, K - 1)\nfor k in range(K):\n    mplot_raw[k] = float(np.mean(rf.predict(X[bin_ids == k])))\nmplot_centered = mplot_raw - float(np.mean(mplot_raw))\n\n# 4. First-Principles ALE (Apley & Zhu 2020: akumulasi gradien lokal bersyarat!)\nlocal_diffs = np.empty(K)\ncounts = np.empty(K)\nfor k in range(K):\n    mask_k = bin_ids == k\n    counts[k] = np.sum(mask_k)\n    X_hi = X[mask_k].copy()\n    X_lo = X[mask_k].copy()\n    X_hi[:, 0] = edges[k + 1]\n    X_lo[:, 0] = edges[k]\n    local_diffs[k] = float(np.mean(rf.predict(X_hi) - rf.predict(X_lo)))\n\nale_uncentered = np.cumsum(local_diffs)\nale_at_mid = np.r_[0.0, ale_uncentered[:-1]] + 0.5 * local_diffs\nale_centered = ale_at_mid - float(np.sum(ale_at_mid * counts) / np.sum(counts))\n\n# Bandingkan terhadap efek sejati murni X0: f1_true(x0) = 2.0 * (x0 - mean(x0))\ntrue_effect = 2.0 * (mids - float(np.mean(mids)))\nslope_pdp = float(np.polyfit(mids, pdp_centered, 1)[0])\nslope_mplot = float(np.polyfit(mids, mplot_centered, 1)[0])\nslope_ale = float(np.polyfit(mids, ale_centered, 1)[0])\n\nrmse_pdp = float(np.sqrt(np.mean((pdp_centered - true_effect) ** 2)))\nrmse_mplot = float(np.sqrt(np.mean((mplot_centered - true_effect) ** 2)))\nrmse_ale = float(np.sqrt(np.mean((ale_centered - true_effect) ** 2)))\n\nprint(f\"Korelasi Empiris Corr(X0, X1) = {np.corrcoef(x0, x1)[0, 1]:.4f} | R2 Train RF = {rf.score(X, y):.4f}\")\nprint(f\"Efek Sejati Murni X0          : Slope = 2.0000 (M-Plot teoretis = 2.0 + 0.92*2.5 = 4.3000)\")\nprint(f\"PDP (Off-Manifold Bias)       : Slope = {slope_pdp:.4f} | RMSE vs Sejati = {rmse_pdp:.4f}\")\nprint(f\"M-Plot (Confounding Bias)     : Slope = {slope_mplot:.4f} | RMSE vs Sejati = {rmse_mplot:.4f}\")\nprint(f\"ALE (Apley & Zhu 2020, K=20)  : Slope = {slope_ale:.4f} | RMSE vs Sejati = {rmse_ale:.4f}\")\nprint(\"Perbandingan pada 5 Kuantil Kunci (x0_mid | Sejati | PDP | M-Plot | ALE):\")\nfor idx in [0, 4, 9, 14, 19]:\n    print(\n        f\"  bin {idx:02d} (x0={mids[idx]:+6.3f}): \"\n        f\"True={true_effect[idx]:+6.3f} | PDP={pdp_centered[idx]:+6.3f} | \"\n        f\"M-Plot={mplot_centered[idx]:+6.3f} | ALE={ale_centered[idx]:+6.3f}\"\n    )",
