          "code": "import numpy as np\nfrom sklearn.ensemble import HistGradientBoostingRegressor\nfrom sklearn.inspection import partial_dependence, permutation_importance\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(42)\nn = 1400\nrho = 0.92\n\n# 4 Fitur: X0 & X1 berkorelasi kuat (0.92), X2 fitur interaksi berlawanan arah, X3 biner segmen {-1, +1}\nz0 = rng.standard_normal(n)\nx0 = z0\nx1 = rho * z0 + np.sqrt(1.0 - rho ** 2) * rng.standard_normal(n)\nx2 = rng.standard_normal(n)\nx3 = rng.choice([-1.0, 1.0], size=n)\nX = np.column_stack([x0, x1, x2, x3])\n\n# Target dengan efek utama berkorelasi + interaksi murni saling meniadakan (3.0 * x2 * x3)\ny = 2.0 * x0 + 2.2 * x1 + 3.0 * x2 * x3 + rng.normal(0.0, 0.35, size=n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.25, random_state=42)\n\nmodel = HistGradientBoostingRegressor(max_depth=5, max_iter=80, min_samples_leaf=15, random_state=42)\nmodel.fit(X_tr, y_tr)\nprint(f\"HistGBDT R2 Test = {model.score(X_te, y_te):.4f}\")\n\n# 1. Permutation Feature Importance (PFI) pada Test Set\npfi = permutation_importance(model, X_te, y_te, n_repeats=10, random_state=42, scoring=\"r2\")\nnames = [\"X0_corr\", \"X1_corr\", \"X2_inter\", \"X3_seg\"]\nprint(\"1. Permutation Feature Importance (penurunan R2 di Test Set):\")\nfor nm, m_val, s_val in zip(names, pfi.importances_mean, pfi.importances_std):\n    print(f\"   {nm:10s}: mean={m_val:.4f} (+/- {s_val:.4f})\")\n\n# 2. Kegagalan PDP rata-rata vs ICE pada interaksi saling meniadakan (X2 * X3)\npd_res = partial_dependence(model, X_te, features=[2], kind=\"both\", grid_resolution=11)\ngrid_x2 = pd_res[\"grid_values\"][0]\npdp_x2 = pd_res[\"average\"][0]\nice_x2 = pd_res[\"individual\"][0]\n\nice_slopes = np.array([np.polyfit(grid_x2, row, 1)[0] for row in ice_x2])\npdp_slope_x2 = float(np.polyfit(grid_x2, pdp_x2, 1)[0])\nslope_neg = float(np.mean(ice_slopes[X_te[:, 3] < 0]))\nslope_pos = float(np.mean(ice_slopes[X_te[:, 3] > 0]))\nprint(\"2. Deteksi Interaksi Saling Meniadakan (3.0 * X2 * X3) via PDP vs ICE:\")\nprint(f\"   Kemiringan PDP Rata-Rata X2 : {pdp_slope_x2:+.4f} (tampak datar / menipu!)\")\nprint(f\"   Kemiringan ICE Segmen X3=-1 : {slope_neg:+.4f} (sejati -3.0)\")\nprint(f\"   Kemiringan ICE Segmen X3=+1 : {slope_pos:+.4f} (sejati +3.0)\")\n\n# 3. Sklearn PDP vs ALE Kuantil pada X0 yang berkorelasi 0.92 dengan X1\nK = 15\nedges = np.quantile(X_te[:, 0], np.linspace(0.0, 1.0, K + 1))\nedges[0] -= 1e-6\nedges[-1] += 1e-6\nmids = 0.5 * (edges[:-1] + edges[1:])\nbin_ids = np.clip(np.digitize(X_te[:, 0], edges) - 1, 0, K - 1)\ndiffs = []\nfor k in range(K):\n    sub = X_te[bin_ids == k]\n    hi, lo = sub.copy(), sub.copy()\n    hi[:, 0], lo[:, 0] = edges[k + 1], edges[k]\n    diffs.append(float(np.mean(model.predict(hi) - model.predict(lo))))\nale_vals = np.r_[0.0, np.cumsum(diffs)[:-1]] + 0.5 * np.array(diffs)\nale_vals -= np.mean(ale_vals)\n\npd_x0 = partial_dependence(model, X_te, features=[0], kind=\"average\", grid_resolution=15)\nslope_pdp_x0 = float(np.polyfit(pd_x0[\"grid_values\"][0], pd_x0[\"average\"][0], 1)[0])\nslope_ale_x0 = float(np.polyfit(mids, ale_vals, 1)[0])\nprint(f\"3. Pemulihan Efek Utama X0 (Sejati +2.00): Sklearn PDP Slope={slope_pdp_x0:+.4f} | ALE Slope={slope_ale_x0:+.4f}\")",
