          "starterCode": "import math\nfrom itertools import combinations\nimport numpy as np\n\ndef exact_shapley_and_kernel_wls(f_fn, x_row: np.ndarray, X_bg: np.ndarray) -> tuple[list[float], float, float]:\n    # TODO: hitung v(S) untuk semua 2^d subset -> phi_exact -> WLS KernelSHAP terkendala -> max_diff & eff_err\n    pass\n\nrng = np.random.default_rng(23)\nX_b = rng.normal(0.0, 1.0, size=(200, 4))\nx_q = np.array([1.5, -1.0, 0.8, 2.0])\nfn = lambda M: 2.0 * M[:, 0] - 1.5 * M[:, 1] + 1.2 * M[:, 0] * M[:, 2] + 0.0 * M[:, 3]\nprint(exact_shapley_and_kernel_wls(fn, x_q, X_b))",
