          "code": "import numpy as np\nfrom scipy.optimize import minimize\n\nrng = np.random.default_rng(42)\n\n# Dataset kredit sintetis (5 fitur):\n# [0] usia (IMMUTABLE), [1] lama_kerja_thn (MONOTONE >= x_0),\n# [2] pendapatan_jt (MUTABLE), [3] rasio_utang (MUTABLE [0.05..0.95]), [4] tabungan_jt (MUTABLE >= 0)\nn = 800\nusia = rng.uniform(22.0, 60.0, size=n)\nkerja = np.clip(0.35 * (usia - 20.0) + rng.normal(0.0, 2.0, size=n), 0.5, 35.0)\npendapatan = np.clip(6.0 + 0.45 * kerja + rng.normal(0.0, 3.0, size=n), 3.0, 40.0)\nutang = np.clip(0.55 - 0.012 * pendapatan + rng.normal(0.0, 0.14, size=n), 0.05, 0.95)\ntabungan = np.clip(1.8 * pendapatan - 12.0 * utang + rng.normal(0.0, 6.0, size=n), 0.0, 100.0)\nX_data = np.column_stack([usia, kerja, pendapatan, utang, tabungan])\nnames = [\"usia\", \"lama_kerja\", \"pendapatan\", \"rasio_utang\", \"tabungan\"]\n\n# MAD (Median Absolute Deviation) untuk jarak scale-invariant Wachter (2017)\nmad = np.maximum(np.median(np.abs(X_data - np.median(X_data, axis=0)), axis=0), 1e-6)\n\n# Model Skor Persetujuan Kredit (Logistic): usia punya bobot kuat agar solver NAIF tergoda mengubah usia!\nw = np.array([-0.14, 0.12, 0.18, -5.20, 0.06])\nb = 7.20\n\ndef logit_fn(x: np.ndarray) -> float:\n    return float(np.dot(w, x) + b)\n\ndef prob_approve(x: np.ndarray) -> float:\n    return 1.0 / (1.0 + np.exp(-np.clip(logit_fn(x), -30.0, 30.0)))\n\n# Pemohon ditolak di zona batas: usia 52 thn, kerja 4 thn, pendapatan 8.5 jt, rasio utang 0.72, tabungan 4.0 jt\nx_rej = np.array([52.0, 4.0, 8.5, 0.72, 4.0])\np_orig = prob_approve(x_rej)\n\n# Solver Wachter (2017): logit hinge loss + smooth Charbonnier L1-MAD agar L-BFGS-B konvergen tajam!\ndef solve_wachter(x0: np.ndarray, bounds, lam: float = 80.0, target_p: float = 0.55) -> np.ndarray:\n    target_z = float(np.log(target_p / (1.0 - target_p)))\n    eps = 1e-8\n\n    def obj(x_cand):\n        hinge = max(0.0, target_z - logit_fn(x_cand)) ** 2\n        dist_mad = float(np.sum(np.sqrt((x_cand - x0) ** 2 + eps) / mad))\n        return lam * hinge + dist_mad\n\n    res = minimize(obj, x0.copy(), method=\"L-BFGS-B\", bounds=bounds, options={\"maxiter\": 400, \"ftol\": 1e-12})\n    return res.x\n\nbounds_naive = [(18.0, 70.0), (0.0, 40.0), (2.0, 50.0), (0.05, 0.95), (0.0, 120.0)]\nbounds_actionable = [\n    (x_rej[0], x_rej[0]),       # usia: IMMUTABLE!\n    (x_rej[1], x_rej[1] + 5.0), # lama_kerja: hanya boleh naik <= +5 thn\n    (x_rej[2], 35.0),           # pendapatan: hanya realistis naik\n    (0.05, x_rej[3]),           # rasio_utang: hanya realistis turun\n    (x_rej[4], 80.0),           # tabungan: naik\n]\n\ncf_naive = solve_wachter(x_rej, bounds_naive, lam=80.0, target_p=0.55)\ncf_act = solve_wachter(x_rej, bounds_actionable, lam=80.0, target_p=0.55)\n\n# Solusi Analitis Tertutup KKT L1-MAD vs L2-MAD pada fitur mutable [1, 2, 3, 4]\nmutable_idx = np.array([1, 2, 3, 4])\ntarget_logit = float(np.log(0.55 / 0.45))\ngap_logit = target_logit - logit_fn(x_rej)\n\n# KKT L1-MAD: mengubah tepat 1 fitur dengan sensitivitas per unit MAD tertinggi |w_j| * MAD_j\nsens_mad = np.abs(w[mutable_idx]) * mad[mutable_idx]\nbest_feat = int(mutable_idx[int(np.argmax(sens_mad))])\ncf_kkt_l1 = x_rej.copy()\ncf_kkt_l1[best_feat] += gap_logit / w[best_feat]\n\n# KKT L2-MAD: sebar perubahan proporsional w_j * MAD_j^2\nw_m = w[mutable_idx]\nm2 = mad[mutable_idx] ** 2\ncf_kkt_l2 = x_rej.copy()\ncf_kkt_l2[mutable_idx] += gap_logit * (w_m * m2) / float(np.sum((w_m ** 2) * m2))\n\nprint(f\"Pemohon Awal (Ditolak): p_approve = {p_orig:.4f} | x = {np.round(x_rej, 2).tolist()}\")\nprint(f\"MAD per fitur         : {np.round(mad, 3).tolist()}\")\nprint(f\"1. Wachter NAIF       : p={prob_approve(cf_naive):.4f} | Delta usia={cf_naive[0]-x_rej[0]:+.2f} thn (MUSTAHIL!) | L1-MAD={np.sum(np.abs(cf_naive-x_rej)/mad):.3f}\")\nprint(f\"2. Wachter ACTIONABLE : p={prob_approve(cf_act):.4f} | Delta usia={cf_act[0]-x_rej[0]:+.2f} thn (TERKUNCI)  | L1-MAD={np.sum(np.abs(cf_act-x_rej)/mad):.3f}\")\nprint(\"   Rincian Recourse Actionable:\")\nfor nm, old_v, new_v in zip(names, x_rej, cf_act):\n    print(f\"     {nm:12s}: {old_v:6.2f} -> {new_v:6.2f} (delta={new_v - old_v:+6.2f})\")\nprint(f\"3. KKT L1-MAD Sparse  : p={prob_approve(cf_kkt_l1):.4f} | Ubah 1 fitur ({names[best_feat]}: {x_rej[best_feat]:.2f}->{cf_kkt_l1[best_feat]:.2f}) | L1-MAD={np.sum(np.abs(cf_kkt_l1-x_rej)/mad):.3f}\")\nprint(f\"4. KKT L2-MAD Smooth  : p={prob_approve(cf_kkt_l2):.4f} | Ubah 4 fitur mutable | L1-MAD={np.sum(np.abs(cf_kkt_l2-x_rej)/mad):.3f} | L2-MAD={np.sqrt(np.sum(((cf_kkt_l2-x_rej)/mad)**2)):.3f}\")",
