          "code": "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.pipeline import make_pipeline\n\n# Simulasi Model Drift (Retraining Kuartalan):\n# Model t=0 dilatih pada 1.000 nasabah; 6 bulan kemudian model t=1 dilatih ulang pada data baru + pengetatan risiko utang!\ndef sample_credit(n_rows, shift_utang=0.0, seed=0):\n    r = np.random.default_rng(seed)\n    X = r.normal(0.0, 1.0, size=(n_rows, 4))  # [0] usia(immut), [1] pendapatan, [2] utang, [3] tabungan\n    z = 0.25 - 0.15 * X[:, 0] + 1.15 * X[:, 1] - (1.60 + shift_utang) * X[:, 2] + 0.85 * X[:, 3]\n    p = 1.0 / (1.0 + np.exp(-z))\n    y = r.binomial(1, p)\n    return X, y\n\nX_t0, y_t0 = sample_credit(1000, shift_utang=0.0, seed=42)\nm_t0 = make_pipeline(StandardScaler(), LogisticRegression(C=1.0)).fit(X_t0, y_t0)\n\nsc = m_t0.named_steps[\"standardscaler\"]\nlr = m_t0.named_steps[\"logisticregression\"]\nw_orig = lr.coef_[0] / sc.scale_\nb_orig = float(lr.intercept_[0] - np.sum(lr.coef_[0] * sc.mean_ / sc.scale_))\n\nX_pool, _ = sample_credit(600, shift_utang=0.0, seed=99)\nrej_X = X_pool[m_t0.predict_proba(X_pool)[:, 1] < 0.45][:150]\n\nretrained_models = []\nfor k in range(15):\n    Xk, yk = sample_credit(1000, shift_utang=0.25, seed=200 + k)\n    retrained_models.append(make_pipeline(StandardScaler(), LogisticRegression(C=1.0)).fit(Xk, yk))\n\nprint(\"=== AUDIT RECOURSE INVALIDATION PASCA-RETRAINING (150 NASABAH x 15 MODEL t+1) ===\")\nmutable_idx = np.array([1, 2, 3])\nw_m = w_orig[mutable_idx]\nw_m_norm2 = float(np.sum(w_m ** 2))\n\nfor target_p in [0.51, 0.58, 0.65, 0.75]:\n    target_logit = float(np.log(target_p / (1.0 - target_p)))\n    cfs = rej_X.copy()\n    dists = []\n    for i in range(len(rej_X)):\n        cur_logit = float(np.dot(w_orig, rej_X[i]) + b_orig)\n        gap = max(0.0, target_logit - cur_logit)\n        delta = gap * w_m / w_m_norm2\n        cfs[i, mutable_idx] += delta\n        dists.append(float(np.linalg.norm(delta)))\n    valid_t0 = float(np.mean(m_t0.predict_proba(cfs)[:, 1] >= 0.50))\n    surv_rates = [float(np.mean(mk.predict_proba(cfs)[:, 1] >= 0.50)) for mk in retrained_models]\n    inval_rate = 1.0 - float(np.mean(surv_rates))\n    print(\n        f\"  Target Margin p*>={target_p:.2f} | Valid t0={100*valid_t0:5.1f}% | \"\n        f\"Survival t+1={100*(1-inval_rate):5.1f}% | Invalidation={100*inval_rate:5.1f}% | \"\n        f\"Mean Cost ||Delta||_2={np.mean(dists):.3f}\"\n    )",
          "expectedOutput": "=== AUDIT RECOURSE INVALIDATION PASCA-RETRAINING (150 NASABAH x 15 MODEL t+1) ===\n  Target Margin p*>=0.51 | Valid t0=100.0% | Survival t+1= 67.6% | Invalidation= 32.4% | Mean Cost ||Delta||_2=0.837\n  Target Margin p*>=0.58 | Valid t0=100.0% | Survival t+1= 97.4% | Invalidation=  2.6% | Mean Cost ||Delta||_2=0.961\n  Target Margin p*>=0.65 | Valid t0=100.0% | Survival t+1= 99.8% | Invalidation=  0.2% | Mean Cost ||Delta||_2=1.090\n  Target Margin p*>=0.75 | Valid t0=100.0% | Survival t+1=100.0% | Invalidation=  0.0% | Mean Cost ||Delta||_2=1.300",
