          "code": "import numpy as np\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import train_test_split\n\nrng = np.random.default_rng(42)\nn = 2000\n\n# Audit 1: Proxy Reconstruction Attack (Mengukur apakah atribut sensitif A bocor lewat fitur non-sensitif)\nA_gender = rng.binomial(1, 0.50, size=n)   # 0=Pria, 1=Wanita\nA_age45 = rng.binomial(1, 0.50, size=n)    # 0=<45, 1=>=45\n\nf_skill = rng.normal(0.0, 1.0, size=n)\nf_edu = rng.normal(0.0, 1.0, size=n)\nf_zip = -1.1 * A_gender + 0.8 * A_age45 + rng.normal(0.0, 0.7, size=n)\nf_gap = 1.2 * A_gender + 0.6 * A_age45 + rng.normal(0.0, 0.75, size=n)\n\nX_clean = np.column_stack([f_skill, f_edu])\nX_with_proxy = np.column_stack([f_skill, f_edu, f_zip, f_gap])\n\nidx_tr, idx_te = train_test_split(np.arange(n), test_size=0.30, stratify=A_gender, random_state=42)\nadv_clean = RandomForestClassifier(n_estimators=25, max_depth=5, random_state=42).fit(X_clean[idx_tr], A_gender[idx_tr])\nadv_proxy = RandomForestClassifier(n_estimators=25, max_depth=5, random_state=42).fit(X_with_proxy[idx_tr], A_gender[idx_tr])\nauc_clean = float(roc_auc_score(A_gender[idx_te], adv_clean.predict_proba(X_clean[idx_te])[:, 1]))\nauc_proxy = float(roc_auc_score(A_gender[idx_te], adv_proxy.predict_proba(X_with_proxy[idx_te])[:, 1]))\n\nprint(\"=== AUDIT 1: PROXY RECONSTRUCTION RISK (ADVERSARY AUC PREDIKSI A DARI X) ===\")\nprint(f\"  Fitur Bersih (skill, edu)       : Adversary AUC = {auc_clean:.4f} (aman ~0.50 acak)\")\nprint(f\"  Dengan Proksi (zip, career_gap) : Adversary AUC = {auc_proxy:.4f} (BAHAYA: A terekam diam-diam!)\")\n\n# Audit 2: Intersectional Fairness Gerrymandering (Kearns et al. 2018)\n# Lolos 4/5ths Rule (DIR >= 0.80) secara marginal pada Gender DAN Usia terpisah,\n# tetapi GAGAL PARAH (DIR < 0.50) pada irisan subgrup (Gender=1 & Age>=45)!\np_sub = np.where(\n    (A_gender == 0) & (A_age45 == 0), 0.60,\n    np.where(\n        (A_gender == 0) & (A_age45 == 1), 0.88,\n        np.where((A_gender == 1) & (A_age45 == 0), 0.88, 0.36),\n    ),\n)\ny_hat = rng.binomial(1, np.clip(p_sub + 0.05 * np.tanh(f_skill), 0.02, 0.98))\n\nsr_g0, sr_g1 = float(y_hat[A_gender == 0].mean()), float(y_hat[A_gender == 1].mean())\nsr_a0, sr_a1 = float(y_hat[A_age45 == 0].mean()), float(y_hat[A_age45 == 1].mean())\ndir_gender = min(sr_g0, sr_g1) / max(sr_g0, sr_g1)\ndir_age = min(sr_a0, sr_a1) / max(sr_a0, sr_a1)\n\nsub_rates = {}\nfor g in [0, 1]:\n    for a in [0, 1]:\n        sub_rates[(g, a)] = float(y_hat[(A_gender == g) & (A_age45 == a)].mean())\nmax_sub = max(sub_rates.values())\nmin_sub = min(sub_rates.values())\ndir_inter = min_sub / max_sub\n\nprint(\"=== AUDIT 2: INTERSECTIONAL FAIRNESS GERRYMANDERING (EEOC 4/5THS RULE = 0.80) ===\")\nprint(f\"  Marginal Gender saja : SR(0)={sr_g0:.3f} vs SR(1)={sr_g1:.3f} | DIR = {dir_gender:.3f} -> {'PASS (>=0.80)' if dir_gender >= 0.80 else 'FAIL'}\")\nprint(f\"  Marginal Usia saja   : SR(0)={sr_a0:.3f} vs SR(1)={sr_a1:.3f} | DIR = {dir_age:.3f} -> {'PASS (>=0.80)' if dir_age >= 0.80 else 'FAIL'}\")\nprint(\"  Audit 4 Subgrup Irisan (Gender x Usia):\")\nfor (g, a), rate in sub_rates.items():\n    print(f\"    Subgrup (G={g}, Age45={a}): Approval Rate = {rate:.3f} | DIR vs Max = {rate/max_sub:.3f}\")\nprint(f\"  Worst-Case Intersectional DIR = {dir_inter:.3f} -> {'PASS' if dir_inter >= 0.80 else 'FAIL PARAH (<0.80)!'}\")",
          "expectedOutput": "=== AUDIT 1: PROXY RECONSTRUCTION RISK (ADVERSARY AUC PREDIKSI A DARI X) ===\n  Fitur Bersih (skill, edu)       : Adversary AUC = 0.5047 (aman ~0.50 acak)\n  Dengan Proksi (zip, career_gap) : Adversary AUC = 0.9445 (BAHAYA: A terekam diam-diam!)\n=== AUDIT 2: INTERSECTIONAL FAIRNESS GERRYMANDERING (EEOC 4/5THS RULE = 0.80) ===\n  Marginal Gender saja : SR(0)=0.740 vs SR(1)=0.613 | DIR = 0.828 -> PASS (>=0.80)\n  Marginal Usia saja   : SR(0)=0.738 vs SR(1)=0.614 | DIR = 0.832 -> PASS (>=0.80)\n  Audit 4 Subgrup Irisan (Gender x Usia):\n    Subgrup (G=0, Age45=0): Approval Rate = 0.599 | DIR vs Max = 0.676\n    Subgrup (G=0, Age45=1): Approval Rate = 0.887 | DIR vs Max = 1.000\n    Subgrup (G=1, Age45=0): Approval Rate = 0.880 | DIR vs Max = 0.993\n    Subgrup (G=1, Age45=1): Approval Rate = 0.340 | DIR vs Max = 0.384\n  Worst-Case Intersectional DIR = 0.384 -> FAIL PARAH (<0.80)!",
